public final class ExtraWidgets {
    private ExtraWidgets(){}
    private static final int[] ROWS={R.id.widget_row0,R.id.widget_row1,R.id.widget_row2},ACTIONS={R.id.widget_action0,R.id.widget_action1,R.id.widget_action2};
    public static PendingIntent open(Context c,int id,String kind,String op,String value){Intent intent=new Intent(c,ExtraActivity.class).putExtra("widget",id).putExtra("module",kind).putExtra("op",op).putExtra("value",value).setData(Uri.parse("nook://extra/"+id+"/"+kind+"/"+op+"/"+Uri.encode(value)));return PendingIntent.getActivity(c,0,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private static PendingIntent actionIntent(Context c,int id,String op){return PendingIntent.getBroadcast(c,0,new Intent(c,WidgetActionReceiver.class).setAction("extra_action").putExtra("widget",id).putExtra("op",op).setData(Uri.parse("nook://extra-action/"+id+"/"+op)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private static void hide(RemoteViews v,int... ids){for(int id:ids)v.setViewVisibility(id,View.GONE);}
    private static void rows(RemoteViews v,List<String> text,PendingIntent[] clicks,boolean compact){for(int n=0;n<Math.min(compact?1:3,text.size());n++){v.setViewVisibility(ROWS[n],View.VISIBLE);v.setTextViewText(ROWS[n],text.get(n));if(clicks!=null&&clicks[n]!=null)v.setOnClickPendingIntent(ROWS[n],clicks[n]);}}
    private static void actions(RemoteViews v,String[] labels,PendingIntent[] clicks){v.setViewVisibility(R.id.widget_actions,View.VISIBLE);for(int n=0;n<3;n++){v.setTextViewText(ACTIONS[n],labels[n]);if(clicks!=null&&clicks[n]!=null)v.setOnClickPendingIntent(ACTIONS[n],clicks[n]);}}
    private static void visual(RemoteViews v,Bitmap b,String description){v.setViewVisibility(R.id.tool_visual,View.VISIBLE);v.setImageViewBitmap(R.id.tool_visual,b);v.setContentDescription(R.id.tool_visual,description);}
    public static RemoteViews render(Context c,int id,String kind,JSONObject config,boolean small,boolean preview){
        boolean compact=small||config.optInt("density",0)==1||WidgetDesign.size(c,id,kind,config,small)[1]<220||config.optInt("variant",0)==1&&!kind.equals("breathing");RemoteViews v=new RemoteViews(c.getPackageName(),WidgetDesign.layout(c,"widget_tools"+(compact?"_compact":""),config));WidgetDesign.Colors colors=WidgetDesign.colors(config,kind);
        hide(v,R.id.widget_meta,R.id.widget_actions,R.id.widget_progress,R.id.widget_time,R.id.widget_date,R.id.widget_row0,R.id.widget_row1,R.id.widget_row2,R.id.tool_visual,R.id.tool_clocks,R.id.extra_chrono);v.setViewVisibility(R.id.widget_title,View.VISIBLE);v.setViewVisibility(R.id.widget_body,View.VISIBLE);v.setTextViewText(R.id.widget_title,Widgets.title(kind));v.setTextViewText(R.id.widget_body,"");v.setTextViewText(R.id.widget_label,config.optString("title",Widgets.title(kind)));v.setImageViewResource(R.id.widget_icon,Widgets.iconResource(kind));v.setImageViewResource(R.id.widget_surface,Widgets.surfaceResource(config,kind));v.setImageViewResource(R.id.tool_visual,0);
        for(int n=0;n<3;n++)v.setImageViewResource(Widgets.BACKGROUND_IMAGES[n+1],Widgets.chipResource(config,kind));for(int image:Widgets.BACKGROUND_IMAGES)v.setInt(image,"setImageAlpha",Widgets.surfaceAlpha(config));for(int text:new int[]{R.id.widget_title,R.id.widget_label,R.id.widget_settings,R.id.widget_row0,R.id.widget_row1,R.id.widget_row2,R.id.widget_action0,R.id.widget_action1,R.id.widget_action2,R.id.extra_chrono})v.setTextColor(text,colors.text);for(int text:new int[]{R.id.widget_body,R.id.widget_meta})v.setTextColor(text,colors.muted);
        PendingIntent setup=LibraryWidgets.configure(c,id,kind);if(!preview){v.setOnClickPendingIntent(R.id.widget_root,setup);v.setOnClickPendingIntent(R.id.widget_settings,setup);}
        boolean big=false;
        if(kind.equals("stopwatch")){long elapsed=ExtraData.stopwatch(c,config);boolean running=config.optBoolean("running",false)&&config.optLong("boot",-2)==ExtraData.boot(c);hide(v,R.id.widget_title,R.id.widget_body);v.setViewVisibility(R.id.extra_chrono,View.VISIBLE);v.setChronometer(R.id.extra_chrono,SystemClock.elapsedRealtime()-elapsed,null,running);actions(v,new String[]{running?"Pause":"Start","Lap","Reset"},preview?null:new PendingIntent[]{actionIntent(c,id,"stopwatch_toggle"),actionIntent(c,id,"stopwatch_lap"),actionIntent(c,id,"stopwatch_reset")});JSONArray laps=config.optJSONArray("laps");if(laps!=null&&!compact){List<String> list=new ArrayList<>();for(int n=Math.max(0,laps.length()-2);n<laps.length();n++)list.add("Lap "+(n+1)+" · "+ExtraData.stopwatchText(laps.optLong(n)));rows(v,list,null,false);}}
        else if(kind.equals("compass")){android.content.SharedPreferences sensor=c.getSharedPreferences("nook_sensors",0);boolean measured=sensor.contains("heading");float heading=sensor.getFloat("heading",0);v.setTextViewText(R.id.widget_title,measured?Math.round(heading)+"°":"Measure a heading");v.setTextViewText(R.id.widget_body,measured?"Last magnetic heading · tap for a live reading":"Open the compass to read your phone's sensors.");if(!compact)visual(v,compass(config,heading,measured),measured?"Last heading "+Math.round(heading)+" degrees":"Compass awaiting a sensor reading");if(!preview)v.setOnClickPendingIntent(R.id.widget_root,open(c,id,kind,"measure",""));}
        else if(kind.equals("recorder")){android.content.SharedPreferences recorder=c.getSharedPreferences("nook_recorder",0);boolean recording=ExtraActivity.recordingActive();v.setTextViewText(R.id.widget_title,recording?"Recording…":recorder.contains("lastFile")?"Last voice memo":"Capture a voice memo");v.setTextViewText(R.id.widget_body,recording?"Stop in the recorder before leaving it.":recorder.contains("lastFile")?ExtraData.duration(recorder.getLong("duration",0))+" · private recording":"Records while the recorder screen is open.");actions(v,new String[]{"Record","Play last","Recorder"},preview?null:new PendingIntent[]{open(c,id,kind,"record",""),open(c,id,kind,"play",""),open(c,id,kind,"open","")});}
        else if(kind.equals("screentime")){if(!ExtraData.usageAllowed(c)){v.setTextViewText(R.id.widget_title,"Connect usage access");v.setTextViewText(R.id.widget_body,"Android-reported app time stays on this phone.");if(!preview)v.setOnClickPendingIntent(R.id.widget_root,open(c,id,kind,"usage",""));}else{ExtraData.Usage usage=ExtraData.usage(c);v.setTextViewText(R.id.widget_title,ExtraData.duration(usage.total));v.setTextViewText(R.id.widget_body,"Today · Android-reported app time");List<String> list=new ArrayList<>();for(int n=0;n<Math.min(3,usage.apps.size());n++)list.add(usage.apps.get(n).getKey()+" · "+ExtraData.duration(usage.apps.get(n).getValue()));rows(v,list,null,compact);if(!preview)v.setOnClickPendingIntent(R.id.widget_root,actionIntent(c,id,"refresh"));big=true;}}
        else if(kind.equals("devicecare")){StatFs disk=new StatFs(Environment.getDataDirectory().getAbsolutePath());ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();c.getSystemService(ActivityManager.class).getMemoryInfo(memory);double used=(disk.getTotalBytes()-disk.getAvailableBytes())/(double)(1024L*1024*1024);v.setTextViewText(R.id.widget_title,String.format(Locale.getDefault(),"%.1f GB",used));v.setTextViewText(R.id.widget_body,"Storage used · "+android.text.format.Formatter.formatFileSize(c,memory.availMem)+" memory available");if(!compact)visual(v,ring(config,(float)(disk.getTotalBytes()-disk.getAvailableBytes())/disk.getTotalBytes(),"Storage"),"Used device storage");if(!preview)v.setOnClickPendingIntent(R.id.widget_root,open(c,id,kind,"storage",""));big=true;}
        else if(kind.equals("tracker")){String type=config.optString("trackerType","activity"),unit=config.optString("unit",type.equals("water")?"ml":type.equals("reading")?"pages":type.equals("sleep")?"minutes":type.equals("steps")?"steps":"");v.setTextViewText(R.id.widget_label,ExtraData.trackerName(config));v.setTextViewText(R.id.widget_title,ExtraData.trackerValue(config,0)+" "+unit);v.setTextViewText(R.id.widget_body,"Logged by you"+(config.optInt("target0",0)>0?" · goal "+config.optInt("target0")+" "+unit:""));if(type.equals("activity")&&!compact){hide(v,R.id.widget_title);visual(v,activity(config),"Your three manually logged activity rings");}else if(config.optInt("target0",0)>0&&!compact)visual(v,ring(config,ExtraData.trackerValue(config,0)/(float)config.optInt("target0"),ExtraData.trackerValue(config,0)+" "+unit),"Manually logged progress");int step=Math.max(1,config.optInt("increment",type.equals("water")?250:1));actions(v,new String[]{"− "+step,"Log","+ "+step},preview?null:new PendingIntent[]{actionIntent(c,id,"tracker_minus"),open(c,id,kind,"log",""),actionIntent(c,id,"tracker_plus")});}
        else if(Set.of("files","bookmarks","shortcuts","maps").contains(kind)){hide(v,R.id.widget_title);List<String> list=new ArrayList<>();PendingIntent[] clicks=new PendingIntent[3];for(int n=0;n<3;n++){String value=config.optString(kind.equals("files")?"file"+n:kind.equals("shortcuts")?"package"+n:kind.equals("maps")?"destination"+n:"url"+n,"");String label=config.optString("name"+n,"");if(label.isEmpty())label=kind.equals("files")?ExtraData.fileName(c,value):kind.equals("shortcuts")&&!value.isEmpty()?ExtraData.appName(c,value):value.isEmpty()?"+ Add "+(kind.equals("maps")?"place":kind.equals("files")?"file":kind.equals("shortcuts")?"app":"page"):value;list.add(label);clicks[n]=preview?null:value.isEmpty()?setup:open(c,id,kind,"item",String.valueOf(n));}rows(v,list,clicks,compact);v.setTextViewText(R.id.widget_body,kind.equals("files")?"Only files you choose are accessible.":kind.equals("maps")?"Saved destinations · opens your maps provider":"Your chosen shortcuts");}
        else if(kind.equals("translate")){v.setTextViewText(R.id.widget_title,"Translate");v.setTextViewText(R.id.widget_body,"Type text, then open Google Translate.");actions(v,new String[]{"Type text","Open","Options"},preview?null:new PendingIntent[]{open(c,id,kind,"type",""),open(c,id,kind,"web",""),setup});}
        else if(kind.equals("breathing")){v.setTextViewText(R.id.widget_title,new String[]{"Box breathing","4–7–8 rhythm","Steady breathing"}[WidgetDesign.clamp(config.optInt("variant",0),0,2)]);v.setTextViewText(R.id.widget_body,"A guided session · tap to begin");if(!compact)visual(v,ring(config,.7f,"Breathe"),"Breathing session shortcut");if(!preview)v.setOnClickPendingIntent(R.id.widget_root,open(c,id,kind,"breathe",""));}
        else if(kind.equals("news")||kind.equals("stocks")){JSONObject data=FeedData.cached(c,kind,config);if(!FeedData.configured(kind,config)){v.setTextViewText(R.id.widget_title,kind.equals("news")?"Choose a news feed":"Connect market data");v.setTextViewText(R.id.widget_body,kind.equals("news")?"Read headlines from a source you select.":"Add your provider key and chosen symbol.");}else if(kind.equals("news")){JSONArray items=data.optJSONArray("items");if(items==null||items.length()==0){v.setTextViewText(R.id.widget_title,"Load your headlines");v.setTextViewText(R.id.widget_body,data.optString("error","Tap Refresh to connect your chosen source."));}else{hide(v,R.id.widget_title);List<String> list=new ArrayList<>();PendingIntent[] clicks=new PendingIntent[3];for(int n=0;n<Math.min(3,items.length());n++){JSONObject item=items.optJSONObject(n);list.add(item.optString("title"));clicks[n]=preview?null:open(c,id,kind,"story",item.optString("url"));}rows(v,list,clicks,compact);v.setTextViewText(R.id.widget_body,(data.optBoolean("offline",false)?"Cached · ":"")+config.optString("feedName","Your feed"));}}else{JSONObject quote=data.optJSONObject("quote");v.setTextViewText(R.id.widget_title,quote==null?config.optString("symbol"):quote.optString("05. price"));v.setTextViewText(R.id.widget_body,quote==null?data.optString("error","Tap Refresh to load the provider quote."):quote.optString("01. symbol")+" · "+quote.optString("10. change percent")+"\nProvider trading date: "+quote.optString("07. latest trading day")+(data.optBoolean("offline",false)?" · Cached":""));big=quote!=null;}actions(v,new String[]{"Refresh","Source","Options"},preview?null:new PendingIntent[]{open(c,id,kind,"refresh",""),open(c,id,kind,"source",""),setup});}
        else if(kind.equals("service")){String family=config.optString("serviceName","Connected app");v.setTextViewText(R.id.widget_label,family);v.setTextViewText(R.id.widget_title,config.optString("cardTitle",family));v.setTextViewText(R.id.widget_body,config.optString("cardDetail","Choose an installed app or enter your own card content."));List<String> list=new ArrayList<>();for(int n=0;n<3;n++){String value=config.optString("detail"+n,"");if(!value.isEmpty())list.add(value);}rows(v,list,null,compact);v.setViewVisibility(R.id.widget_meta,View.VISIBLE);v.setTextViewText(R.id.widget_meta,config.optString("package0","").isEmpty()?"Manual card · no private account data":"App shortcut · no private account data");if(!preview&&!config.optString("package0","").isEmpty())v.setOnClickPendingIntent(R.id.widget_root,open(c,id,kind,"item","0"));}
        else if(kind.equals("tips")){int index=Math.floorMod(config.optInt("tip",LocalDate.now().getDayOfYear()),ExtraData.TIPS.length);v.setTextViewText(R.id.widget_title,"A little tip");v.setTextViewText(R.id.widget_body,ExtraData.TIPS[index]);actions(v,new String[]{"Previous","Options","Next"},preview?null:new PendingIntent[]{actionIntent(c,id,"tip_previous"),setup,actionIntent(c,id,"tip_next")});}
        WidgetDesign.surfaces(c,v,id,kind,config,compact,new int[]{R.id.widget_action_bg0,R.id.widget_action_bg1,R.id.widget_action_bg2});WidgetDesign.dedicated(c,v,id,kind,config,compact);v.setTextViewTextSize(R.id.extra_chrono,android.util.TypedValue.COMPLEX_UNIT_SP,(compact?36:48)*WidgetDesign.scale(config));if(big)v.setTextViewTextSize(R.id.widget_title,android.util.TypedValue.COMPLEX_UNIT_SP,(compact?28:38)*WidgetDesign.scale(config));if(compact)v.setInt(R.id.widget_body,"setMaxLines",1);return v;
    }
    public static void action(Context c,int id,String op){AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);if(info==null||op==null)return;String provider=Widgets.kindOf(info.provider);JSONObject root=Store.config(c,id);String kind=provider.equals("universal")?UniversalWidget.currentPage(root):provider;if(ExtraKinds.index(kind)<0)return;JSONObject config=provider.equals("universal")?UniversalWidget.pageSettings(root,kind):root;
        if(kind.equals("stopwatch")){long elapsed=ExtraData.stopwatch(c,config);if(op.equals("stopwatch_reset")){ExtraData.put(config,"elapsed",0);ExtraData.put(config,"running",false);config.remove("laps");}else if(op.equals("stopwatch_toggle")){boolean running=config.optBoolean("running",false)&&config.optLong("boot",-2)==ExtraData.boot(c);ExtraData.put(config,"elapsed",elapsed);ExtraData.put(config,"running",!running);ExtraData.put(config,"started",SystemClock.elapsedRealtime());ExtraData.put(config,"boot",ExtraData.boot(c));}else if(op.equals("stopwatch_lap")){JSONArray laps=config.optJSONArray("laps");if(laps==null)laps=new JSONArray();if(laps.length()<50)laps.put(elapsed);ExtraData.put(config,"laps",laps);}}
        if(kind.equals("tracker")&&(op.equals("tracker_plus")||op.equals("tracker_minus"))){int current=ExtraData.trackerValue(config,0),step=Math.max(1,config.optInt("increment",config.optString("trackerType").equals("water")?250:1));ExtraData.put(config,"amount0",Math.max(0,Math.min(1000000,current+(op.endsWith("plus")?step:-step))));ExtraData.put(config,"trackedDay",LocalDate.now().toString());}
        if(kind.equals("tips"))ExtraData.put(config,"tip",config.optInt("tip",LocalDate.now().getDayOfYear())+(op.equals("tip_next")?1:-1));Store.config(c,id,root);Widgets.update(c,id,provider);
    }
    private static Bitmap ring(JSONObject config,float amount,String label){Bitmap b=Bitmap.createBitmap(600,260,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(3);WidgetDesign.Colors colors=WidgetDesign.colors(config,"tracker");p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(20);p.setStrokeCap(Paint.Cap.ROUND);p.setColor(colors.chip);canvas.drawCircle(300,130,100,p);p.setColor(colors.accent);canvas.drawArc(200,30,400,230,-90,Math.max(0,Math.min(1,amount))*360,false,p);p.setStyle(Paint.Style.FILL);p.setColor(colors.text);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(26);p.setTypeface(Typeface.create("sans-serif-medium",0));canvas.drawText(label,300,140,p);return b;}
    private static Bitmap activity(JSONObject config){Bitmap b=Bitmap.createBitmap(600,270,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(3);int[] colors={0xfff03a7e,0xff9bd522,0xff30ced6};p.setStrokeWidth(17);p.setStrokeCap(Paint.Cap.ROUND);p.setStyle(Paint.Style.STROKE);WidgetDesign.Colors scheme=WidgetDesign.colors(config,"tracker");for(int n=0;n<3;n++){float r=107-n*24;p.setColor(scheme.chip);canvas.drawCircle(300,135,r,p);p.setColor(scheme.monochrome?scheme.text:colors[n]);float target=config.optInt("target"+n,0);canvas.drawArc(300-r,135-r,300+r,135+r,-90,target>0?Math.min(1,ExtraData.trackerValue(config,n)/target)*360:0,false,p);}return b;}
    private static Bitmap compass(JSONObject config,float heading,boolean measured){Bitmap b=Bitmap.createBitmap(600,260,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(3);WidgetDesign.Colors colors=WidgetDesign.colors(config,"compass");p.setColor(colors.muted);p.setStrokeWidth(2);for(int n=0;n<36;n++){double a=n*Math.PI/18;canvas.drawLine(300+(float)Math.sin(a)*100,130-(float)Math.cos(a)*100,300+(float)Math.sin(a)*(n%3==0?88:95),130-(float)Math.cos(a)*(n%3==0?88:95),p);}p.setColor(colors.accent);if(measured){canvas.save();canvas.rotate(-heading,300,130);Path arrow=new Path();arrow.moveTo(300,32);arrow.lineTo(286,140);arrow.lineTo(314,140);arrow.close();canvas.drawPath(arrow,p);canvas.restore();}p.setTextAlign(Paint.Align.CENTER);p.setTextSize(22);canvas.drawText("N",300,22,p);return b;}
}
